import 'server-only';
import { createHmac, timingSafeEqual } from 'node:crypto';

/**
 * THE SECOND LEG OF A DOUBLE OPT IN, stateless, the same shape as OutRip's recovery token
 * (buyer.ts): a signed, expiring string rather than a row in a tokens table. Nothing is ever
 * sent to an address that has not clicked one of these, which is what makes the reminder list
 * a list of people who asked rather than a list of addresses somebody typed into a box.
 */

const TTL_MS = 24 * 60 * 60_000;

function secret(): string {
  const s = process.env.STRIPE_SECRET_KEY;
  if (!s) throw new Error('no signing secret available for the opt-in token');
  return s;
}

function sign(payload: string): string {
  return createHmac('sha256', secret()).update(payload).digest('base64url');
}

function verify(payload: string, given: string): boolean {
  const want = sign(payload);
  if (given.length !== want.length) return false;
  try { return timingSafeEqual(Buffer.from(given), Buffer.from(want)); } catch { return false; }
}

export function optinToken(playerId: string, email: string, now = Date.now()): string {
  const exp = now + TTL_MS;
  const payload = `optin:${playerId}:${email}:${exp}`;
  return `${playerId}.${Buffer.from(email).toString('base64url')}.${exp}.${sign(payload)}`;
}

export function readOptinToken(token: string, now = Date.now()): { playerId: string; email: string } | null {
  const parts = token.split('.');
  if (parts.length !== 4) return null;
  const [playerId, emailB64, expRaw, mac] = parts;
  const exp = Number(expRaw);
  if (!Number.isFinite(exp)) return null;
  let email: string;
  try { email = Buffer.from(emailB64, 'base64url').toString('utf8'); } catch { return null; }
  const payload = `optin:${playerId}:${email}:${exp}`;
  if (!verify(payload, mac)) return null;
  if (now > exp) return null;
  return { playerId, email };
}

